  (1987, 'https://www.fsbt.com/fee-schedule', 'html', '11f41610b9886c446852d5457297b7a85dc34c7434a28fbf1d70aa258731362a', 'confirmed', 'MN answer key: keyed line by line by the Knox thread from stored text 2017 (not yet checked by a person). Web-page fee schedule (effective Aug 31, 2023) with names and amounts on separate lines; source_line is the amount line. Foreign outgoing wire reads ''$25.00 per transfer and $30.00 additional'' (total unclear). Waivers (seniors 65+, Croix Club, First Class, eStatement) kept as conditions rather than separate $0 rows. Safe deposit drilling cost ''determined at opening'' recorded as varies. International ATM fees are percentages (varies).', 'knox-hand-key-states-2026-10-06'),
  (2119, 'https://founders.bank/wp-content/uploads/2025/11/Deposit-and-Treasury-Fee-Schedule-OnBoard.pdf', 'text_pdf', '03a9d3c4ee490ad53eff0cc750f1bd892d14a388bfad6dd64a0560d626db6a5f', 'prefilled', 'stratum: community_mid / bank / text_pdf (DC)', 'manual-read-of-stored-text-2026-10-04'),
