-- Answer keys onto prod. answer_key_institutions and answer_key_fees were empty, so no agent's
-- learning (pipeline_feedback 'answer_key' rows), Atlas's answer-key score or Darwin's batch scoring
-- ever saw the hand-keyed keys; they lived only in /mnt/project-files/answer-key and the Knox gate
-- fixtures. This seeds them.
--
--   * 62 banks keyed line by line by the Knox thread (Texas set and the 7-state set; the same
--     keys the Knox answer-key CI gate runs on). status 'confirmed', confirmed_by 'knox-hand-key':
--     checked line by line against the stored text, not yet by a person. One document per bank
--     (the table allows one); where a bank had two keyed copies, the current (not superseded) one.
--   * 55 banks from the 2026-10-04 prefill draft, status 'prefilled' (scoring and learning read
--     only confirmed rows; a person confirms them on /admin/answer-key).
--   * 3031 fee rows (2321 confirmed, 710 prefilled).
--
-- Data change: inserts only. Never touches an institution already in the answer key (ON CONFLICT DO
-- NOTHING), and adds fee rows only to a key row this file created that has none yet, so re-running is a
-- no-op. Banks missing from institution_sources are skipped.

BEGIN;

CREATE TEMP TABLE _ak_seed_inst (institution_id BIGINT, document_url TEXT, document_type TEXT, content_hash TEXT,
  status TEXT, notes TEXT, prefill_source TEXT) ON COMMIT DROP;
CREATE TEMP TABLE _ak_seed_fee (institution_id BIGINT, canonical_key TEXT, amount NUMERIC(12,2), amount_kind TEXT,
  frequency TEXT, conditions TEXT, source_line TEXT, uncertain BOOLEAN) ON COMMIT DROP;


