SELECT s.institution_id, s.document_url, s.document_type, s.content_hash, s.status, s.notes, s.prefill_source, NOW(),
       CASE WHEN s.status = 'confirmed' THEN 'knox-hand-key' END,
       CASE WHEN s.status = 'confirmed' THEN NOW() END
  FROM _ak_seed_inst s
  JOIN public.institution_sources i ON i.id = s.institution_id
ON CONFLICT (institution_id) DO NOTHING;

   status, confirmed_by, confirmed_at)
SELECT ak.id, f.canonical_key, f.amount, f.amount_kind, f.frequency, f.conditions, f.source_line, f.uncertain,
       ak.status, ak.confirmed_by, ak.confirmed_at
  FROM _ak_seed_fee f
  JOIN _ak_seed_inst s ON s.institution_id = f.institution_id
  JOIN public.answer_key_institutions ak ON ak.institution_id = f.institution_id AND ak.prefill_source = s.prefill_source
 WHERE NOT EXISTS (SELECT 1 FROM public.answer_key_fees x WHERE x.answer_key_institution_id = ak.id);

COMMIT;
